use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let matrix = input.as_array().unwrap();
    let n = matrix.len();
    let m = matrix[0].as_array().unwrap().len();
    let mut result = vec![vec![0; n]; m];

    for i in 0..n {
        for j in 0..m {
            result[j][n - 1 - i] = matrix[i][j].as_i64().unwrap();
        }
    }

    Value::Array(result.into_iter().map(|v| Value::Array(v.into_iter().map(|x| Value::Number(x.into())).collect())).collect())
}
